#!/usr/bin/env node
/**
 * Tests for hooks/edit-nudge.js. Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Each case gets its own CLAUDE_CONFIG_DIR, so the per-turn counter and the pruning only ever touch
 * a temp directory. The hook is driven the way the harness drives it: one PostToolUse payload per
 * edit, one user entry in the session transcript per user prompt.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, appendFileSync, readFileSync, existsSync, utimesSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const HOOK = join(ROOT, 'hooks', 'edit-nudge.js');
const created = [];
process.on('exit', () => {
  for (const dir of created) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp */ } }
});

function sandbox() {
  const config = mkdtempSync(join(tmpdir(), 'editnudge-'));
  created.push(config);
  return config;
}

/** The hook's `additionalContext` for one payload, '' when it said nothing. */
function fire(config, payload) {
  const r = spawnSync(process.execPath, [HOOK], {
    input: typeof payload === 'string' ? payload : JSON.stringify(payload),
    encoding: 'utf8',
    env: { ...process.env, CLAUDE_CONFIG_DIR: config },
  });
  assert.equal(r.status, 0, r.stderr);
  return r.stdout ? JSON.parse(r.stdout).hookSpecificOutput : null;
}

/** The session's own transcript, beside the sandboxed config: the hook tells turns from it. */
const transcriptOf = (config) => join(config, 'session.jsonl');
const edit = (config, extra = {}) => fire(config, {
  session_id: 'sess-1', hook_event_name: 'PostToolUse', tool_name: 'Edit', tool_input: { file_path: 'a.cs' },
  transcript_path: transcriptOf(config), ...extra,
});
let uuid = 0;
const line = (config, entry) => appendFileSync(transcriptOf(config), `${JSON.stringify({ uuid: `u${++uuid}`, ...entry })}\n`);
/** A user prompt as the harness records it: a user entry in the session transcript, nothing fired. */
const prompt = (config) => line(config, { type: 'user', message: { role: 'user', content: 'x' } });
/** A turn's own traffic: an edit's tool_use and its tool_result, plus a big output, none of them a prompt. */
const traffic = (config, bytes = 200) => {
  line(config, { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: `t${uuid}`, name: 'Edit', input: {} }] } });
  line(config, { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: `t${uuid}`, content: 'y'.repeat(bytes) }] } });
};

test('the third edit of a turn nudges once, in one line, towards the implementer', () => {
  const config = sandbox();
  assert.equal(edit(config), null, 'first');
  assert.equal(edit(config), null, 'second');
  const third = edit(config);
  assert.equal(third.hookEventName, 'PostToolUse');
  assert.match(third.additionalContext, /^[^\n]*\bimplementer\b[^\n]*$/);
  assert.equal(edit(config), null, 'fourth: already said this turn');
  assert.equal(edit(config), null, 'fifth');
});

test('a new user prompt in the transcript starts the count again, also after a turn interrupted with no Stop', () => {
  const config = sandbox();
  prompt(config);
  for (let i = 0; i < 3; i += 1) { traffic(config); edit(config); }
  prompt(config);
  assert.equal(edit(config), null);
  assert.equal(edit(config), null);
  assert.match(edit(config).additionalContext, /implementer/, 'the next turn nudges again at its own third edit');
  edit(config);
  prompt(config);                               // typed after an Esc: the counter was at 4, no hook ran in between
  assert.equal(edit(config), null);
  assert.equal(edit(config), null);
  assert.match(edit(config).additionalContext, /implementer/);
});

test('the prompt is found however much other sessions type: history.jsonl is not read', () => {
  const config = sandbox();
  prompt(config);
  for (let i = 0; i < 3; i += 1) edit(config);
  // 20 busy sessions: a large shared history with no line of this session in its tail.
  writeFileSync(join(config, 'history.jsonl'), `${JSON.stringify({ display: 'x', timestamp: Date.now(), sessionId: 'sess-1' })}\n`
    + `${JSON.stringify({ display: 'y'.repeat(200), timestamp: Date.now(), sessionId: 'other' })}\n`.repeat(2000));
  prompt(config);
  traffic(config, 300_000);                     // a big tool output after the prompt
  assert.equal(edit(config), null);
  assert.equal(edit(config), null);
  assert.match(edit(config).additionalContext, /implementer/, 'a new turn, told from the transcript');
});

test('a tool result, a task notification or a peer message is no new prompt; no transcript keeps the count', () => {
  const config = sandbox();
  prompt(config);
  edit(config);
  traffic(config);
  line(config, { type: 'user', origin: { kind: 'task-notification' }, message: { role: 'user', content: '<task-notification>done</task-notification>' } });
  edit(config);
  line(config, { type: 'user', message: { role: 'user', content: '<cross-session-message from="x">hi</cross-session-message>' } });
  assert.match(edit(config).additionalContext, /implementer/, 'still the third edit of this turn');
  const bare = sandbox();
  for (let i = 0; i < 2; i += 1) assert.equal(edit(bare), null);
  assert.match(edit(bare).additionalContext, /implementer/);
});

test('Write counts like Edit; other tools and other events do not', () => {
  const config = sandbox();
  edit(config);
  edit(config, { tool_name: 'Write' });
  assert.equal(edit(config, { tool_name: 'Read' }), null, 'a Read is not an edit');
  assert.equal(fire(config, { session_id: 'sess-1', hook_event_name: 'Stop' }), null);
  assert.match(edit(config, { tool_name: 'Write' }).additionalContext, /implementer/, 'the third real edit');
});

test('MultiEdit counts like Edit', () => {
  const config = sandbox();
  edit(config, { tool_name: 'MultiEdit' });
  edit(config, { tool_name: 'MultiEdit' });
  assert.match(edit(config, { tool_name: 'MultiEdit' }).additionalContext, /implementer/, 'the third edit');
});

test('edits made inside a subagent are not counted (agent_id, or a subagents transcript)', () => {
  const config = sandbox();
  for (let i = 0; i < 5; i += 1) assert.equal(edit(config, { agent_id: 'agent-7', agent_type: 'implementer' }), null);
  const sub = join('C:', 'x', 'projects', 'p', 'sess-1', 'subagents', 'agent-7.jsonl');
  for (let i = 0; i < 5; i += 1) assert.equal(edit(config, { transcript_path: sub }), null);
  assert.equal(edit(config), null, 'the main session starts from zero');
  assert.equal(edit(config), null);
  assert.match(edit(config).additionalContext, /implementer/);
});

test('a Write or Edit of a scratch file under the system temp directory is not counted', () => {
  const config = sandbox();
  const scratch = join(tmpdir(), 'claude', 'session', 'scratchpad');
  mkdirSync(scratch, { recursive: true });
  created.push(join(tmpdir(), 'claude', 'session'));
  const report = join(scratch, 'report.md');
  writeFileSync(report, 'x');
  for (let i = 0; i < 5; i += 1) {
    assert.equal(edit(config, { tool_name: i % 2 ? 'Edit' : 'Write', tool_input: { file_path: report } }), null, 'scratch ' + i);
  }
  // A relative path is read against the payload's cwd.
  assert.equal(edit(config, { tool_input: { file_path: 'report.md' }, cwd: scratch }), null, 'relative to cwd');
  assert.equal(edit(config), null, 'a repository file: first');
  assert.equal(edit(config), null, 'second');
  assert.match(edit(config).additionalContext, /implementer/, 'third real edit');
});

test('doc and data files are not counted: three .md edits are silent, two .md plus three .js nudge on the third .js', () => {
  const at = (config, file) => edit(config, { tool_input: { file_path: file } });
  const quiet = sandbox();
  for (const f of ['a.md', 'B.JSON', 'c.yml']) assert.equal(at(quiet, f), null, f);
  assert.equal(at(quiet, 'd.js'), null, 'only the first code edit');
  const config = sandbox();
  assert.equal(at(config, 'a.md'), null);
  assert.equal(at(config, 'b.md'), null);
  assert.equal(at(config, 'a.js'), null, 'first js');
  assert.equal(at(config, 'b.js'), null, 'second js');
  assert.match(at(config, 'c.js').additionalContext, /implementer/, 'third js');
});

test('parallel sessions keep separate counts', () => {
  const config = sandbox();
  edit(config, { session_id: 'a' });
  edit(config, { session_id: 'a' });
  edit(config, { session_id: 'b' });
  assert.equal(edit(config, { session_id: 'b' }), null);
  assert.match(edit(config, { session_id: 'a' }).additionalContext, /implementer/);
});

test('no usable session id, or a payload that is not JSON → silent, exit 0', () => {
  const config = sandbox();
  for (const session_id of [undefined, '', '../escape', 'a/b', 'x'.repeat(200)]) {
    for (let i = 0; i < 4; i += 1) assert.equal(edit(config, { session_id }), null);
  }
  assert.equal(fire(config, 'not json at all'), null);
  assert.equal(fire(config, ''), null);
});

test('old counter files are pruned when the nudge fires, recent ones are kept', () => {
  const config = sandbox();
  mkdirSync(join(config, '.cache'), { recursive: true });
  const old = join(config, '.cache', 'edits-gone.json');
  const recent = join(config, '.cache', 'edits-other.json');
  writeFileSync(old, '{}');
  writeFileSync(recent, '{}');
  const past = (Date.now() - 4 * 24 * 60 * 60 * 1000) / 1000;
  utimesSync(old, past, past);
  for (let i = 0; i < 3; i += 1) edit(config);
  assert.ok(!existsSync(old));
  assert.ok(existsSync(recent));
});

test('settings.json wires it, through hooks/nudges.js, on PostToolUse (Write|Edit|MultiEdit) only: no node per prompt, and the scripts exist', () => {
  const settings = JSON.parse(readFileSync(join(ROOT, 'settings.json'), 'utf8'));
  const wired = (group) => (group?.hooks ?? []).some((h) => (h.args ?? []).join(' ').includes('nudges.js'));
  assert.ok(settings.hooks.PostToolUse.some((g) => g.matcher === 'Write|Edit|MultiEdit' && wired(g)), 'PostToolUse Write|Edit|MultiEdit');
  assert.ok(!(settings.hooks.UserPromptSubmit ?? []).some(wired), 'no UserPromptSubmit entry');
  assert.ok(existsSync(HOOK));
  assert.ok(existsSync(join(ROOT, 'hooks', 'nudges.js')));
});
